# ATOP+R2: ATOP plus group subadditivity generated by the relations q ≡ y(q) of the quadratic corners q = e_a + e_b ∉ T
# (cylinder lemma: y(q) ∈ T, supp y ∩ {a,b} = ∅).  Relation vectors v_q = q − y(q) ∈ Λ.  For u, v ∈ T∖0 and integer
# combinations s = u + v − Σ k_q v_q landing in T (|k_q| ≤ K), add r(s) ≤ r(u) + r(v).  Needs the tile's residues phi
# only to find y(q); the constraints themselves are residue-free given the relations.
import sys, itertools
import numpy as np
from scipy.optimize import linprog
from scipy.sparse import lil_matrix
sys.path.insert(0, 'src'); sys.path.insert(0, 'src/scratch')
def atop_r2(T, phi, m, K=3, use_rel=True, lower=False, integral=False, ret=False, tlim=200):
    T = sorted(T); d = len(T[0]); Ts = set(T); idx = {z: i for i, z in enumerate(T)}; n = len(T)
    U = [tuple(int(i == a) for i in range(d)) for a in range(d)]
    add = lambda x, y: tuple(p + q for p, q in zip(x, y))
    X = [x for x in T if all(add(x, u) not in Ts for u in U)]
    byphi = {phi[z] % m: z for z in T}
    rels = []
    if use_rel:
        for a in range(d):
            for b in range(a, d):
                q = add(U[a], U[b])
                if q in Ts: continue
                y = byphi[(phi[U[a]] + phi[U[b]]) % m]
                rels.append(tuple(p - r for p, r in zip(q, y)))
    nv = n + n * n
    Aeq = lil_matrix((3 * n + 1, nv)); beq = np.zeros(3 * n + 1); row = 0
    for z in range(n):
        Aeq[row, z] = 1
        for j in range(n): Aeq[row, n + z * n + j] = -j
        row += 1
    for z in range(n):
        for j in range(n): Aeq[row, n + z * n + j] = 1
        beq[row] = 1; row += 1
    for j in range(n):
        for z in range(n): Aeq[row, n + z * n + j] = 1
        beq[row] = 1; row += 1
    Aeq[row, idx[tuple([0] * d)]] = 1; row += 1
    sub = set()
    ks = list(itertools.product(range(-K, K + 1), repeat=len(rels)))
    for i, u in enumerate(T):
        if sum(u) == 0: continue
        for v in T[i:]:
            if sum(v) == 0: continue
            s0 = add(u, v)
            for k in ks:
                s = tuple(s0[c] - sum(kk * rv[c] for kk, rv in zip(k, rels)) for c in range(d))
                if s in Ts and sum(s) > 0: sub.add((idx[s], idx[u], idx[v]))
    sub = sorted(sub)
    nr = len(sub) * (2 if lower else 1)
    Aub = lil_matrix((max(1, nr), nv)); bub = np.zeros(max(1, nr))
    for k, (z, x, y) in enumerate(sub): Aub[k, z] += 1; Aub[k, x] -= 1; Aub[k, y] -= 1
    if lower:   # quasi-additivity: r(x) + r(y) - m <= r(z)
        for k, (z, x, y) in enumerate(sub):
            kk = len(sub) + k; Aub[kk, z] -= 1; Aub[kk, x] += 1; Aub[kk, y] += 1; bub[kk] = m
    cost = np.zeros(nv)
    for u in X: cost[idx[u]] -= (sum(u) + d)
    if integral:
        from scipy.optimize import milp, LinearConstraint, Bounds
        integ = np.zeros(nv); integ[n:] = 1
        r = milp(cost, constraints=[LinearConstraint(Aub.tocsr(), -np.inf, bub), LinearConstraint(Aeq.tocsr(), beq, beq)],
                 integrality=integ, bounds=Bounds(0, np.inf), options={'time_limit': tlim, 'disp': False})
        if r.x is None: return None
        r.fun = r.fun; 
    else:
        r = linprog(cost, A_ub=Aub.tocsr(), b_ub=bub, A_eq=Aeq.tocsr(), b_eq=beq, bounds=[(0, None)] * nv, method='highs')
        assert r.status == 0
    lhs = -r.fun + sum(sum(u) + d for u in X); rhs = n * ((d + 1) * n + d - 1) / 2
    if ret: return (rhs - lhs) / rhs, {z: r.x[idx[z]] for z in T}, X, getattr(r, 'mip_dual_bound', None)
    return (rhs - lhs) / rhs, len(rels), len(sub)
if __name__ == '__main__':
    from ns import NS
    from cl import factorizations_down_set
    for g in sys.argv[1:]:
        s = NS.from_generators(list(map(int, g.split(','))))
        Pp, best = factorizations_down_set(s, 'grlex'); T = list(best.values()); lam = {x: w for w, x in best.items()}
        phi = {x: lam[x] % s.m for x in T}
        a0 = atop_r2(T, phi, s.m, use_rel=False); a1 = atop_r2(T, phi, s.m)
        b0 = atop_r2(T, phi, s.m, use_rel=False, lower=True); b1 = atop_r2(T, phi, s.m, lower=True)
        print(f'<{g}> m={s.m}: ATOP {a0[0]:+.4f}  ATOP+R2 {a1[0]:+.4f}  ATOP2 {b0[0]:+.4f}  ATOP2+R2 {b1[0]:+.4f}', flush=True)
